  html:'<div class="t-wkw"><table class="t-wk"><thead><tr><th>Pegawai</th><th>Tim</th>'+W.map(ds=>'<th class="t-dc '+(ds===t?'t-td':'')+'" title="'+H(fmt(ds)+(defC(ds)==='h'?' · jadwal WFH':'')+(ds===t?' · hari ini':''))+'">'+HR[dow(ds)].slice(0,3)+', '+(+ds.slice(8))+' '+BLN[+ds.slice(5,7)-1].slice(0,3)+'</th>').join('')+'<th style="text-align:left">Beban bulan ini</th></tr></thead><tbody>'+
  rows.slice(pg.from,pg.to).map(p=>{const l=LOAD[p.n]||0;return '<tr><td><button type="button" class="t-who2" data-tp="'+H(p.n)+'">'+av(p,'sm',false)+'<span><b>'+H(nk(p))+'</b>'+(p.k?' <span class="t-chip t-ke">Katim'+(p.t?' '+H(tshort(p.t)):'')+'</span>':'')+(isTmp(p)?' <span class="t-chip t-tmp">'+H(p.jen)+'</span>':'')+'<small>'+H(p.n)+'</small></span></button></td><td>'+(p.t?tchip(p):'<span class="t-chip t-gr">—</span>')+'</td>'+W.map(ds=>{const c=code(p,ds),m=mtg(p,ds),o=ovr(p,ds),k=p.n+'|'+ds,ed=canEdit()&&(c==='o'||c==='h');return '<td class="'+(ds===t?'t-td':'')+'" style="position:relative"><button type="button" class="t-cell t-'+c+' '+(ed?'t-ed':'')+' '+(o?'t-ovr':'')+'" '+(ed?'data-tcell="'+H(k)+'"':'tabindex="-1"')+' title="'+H(SL[c]+(o&&o.r?' · '+o.r:'')+(m?' · '+m+' rapat':'')+(ed?' · klik untuk ubah':''))+'">'+SLs[c]+(m&&c!=='c'&&c!=='l'?'<span class="t-m">'+m+'</span>':'')+'</button>'+(ST.cpop===k?cellPop(p,ds):'')+'</td>'}).join('')+'<td><div class="t-load" title="'+l+' kegiatan bulan ini"><i><b style="width:'+Math.min(100,l/mx*100)+'%;background:'+(l>=mx*0.85?'var(--t-c)':l>=mx*0.55?'#D99A00':'var(--t-o)')+'"></b></i><span class="t-xs">'+l+'</span></div></td></tr>'}).join('')+(rows.length?'':'<tr><td colspan="8" class="t-empty">Tidak ada pegawai</td></tr>')+'</tbody><tfoot><tr><td>Hadir di kantor (semua)</td><td></td>'+office.map((n,i)=>'<td class="'+(W[i]===t?'t-td':'')+'">'+n+'/'+P.length+'</td>').join('')+'<td></td></tr></tfoot></table></div>',
