 const ovrs=Object.entries(C().ovr).map(([k,o])=>{const[n,ds]=k.split('|');return Object.assign({k,n,ds},o)}).filter(x=>x.c!==defC(x.ds)&&x.ds>=addD(t,-30)).sort((a,b)=>b.ds.localeCompare(a.ds));
