  L.slice(pg.from,pg.to).map(c=>{const p=pn(c.n);let over=false;for(let d=c.a;d<=c.b&&!over;d=addD(d,1))over=checkDay(d).some(v=>v.s==='Pusmantap'||v.s===p.t);return '<tr><td>'+nkc(c.n)+' <span class="t-xs t-muted">'+H(tshort(p.t)||'—')+'</span></td><td class="t-sm">'+H(c.jn)+(c.khusus?' <span class="t-chip t-cm" title="Cuti yang sedang/sudah diambil; menimpa rencana yang tumpang tindih">diambil</span>':'')+'</td><td class="t-sm">'+fmtS(c.a)+(c.a!==c.b?'–'+fmtS(c.b):'')+' '+(over?'<span class="t-chip t-b-c" title="Ada hari yang melewati batas">'+ic('alert','s')+'</span>':'')+'</td><td class="t-sm">'+wdN(c)+'</td><td style="text-align:right">'+(canEdit()?'<button type="button" class="t-btn t-sm" data-tcf="'+H(c.n)+'|'+c.ci+'">'+ic('edit','s')+'Ubah</button>':'')+'</td></tr>'}).join('')+(L.length?'':'<tr><td colspan="5" class="t-empty">Belum ada rencana cuti</td></tr>')+'</tbody></table>';
 const rule=C().rule,ruleH='<span class="t-rinfo" tabindex="0" aria-label="Aturan batas cuti">'+ic('info','s')+'<span>Maks. '+rule.pct+'% cuti / hari'+(ruleAll()?'':' saat musim libur')+' · '+({team:'Per tim',all:'Seluruh Pusmantap',both:'Per tim & seluruh Pusmantap'})[rule.scope]+'</span><span class="t-rpop" role="tooltip"><b>Aturan batas cuti</b><span><small>Batas dihitung</small>'+({team:'Per tim',all:'Seluruh Pusmantap',both:'Per tim & seluruh Pusmantap'})[rule.scope]+'</span><span><small>Maks. cuti per hari</small>'+rule.pct+'% (dibulatkan ke bawah)</span><span><small>Berlaku</small>'+(ruleAll()?'Sepanjang tahun':MUSIM.filter(x=>(rule.musim||{})[x[0]]!==false).map(x=>x[1]).join(', ')||'—')+'</span><span><small>Dihitung</small>Semua jenis cuti</span><em>Rencana tersimpan = disetujui & langsung masuk pemantauan. Rencana yang melewati batas ditolak, kecuali Cuti Sakit/Melahirkan (tetap tersimpan dan ditandai agar diatur).</em></span></span>';
