function unitList(){const k=kpCfg();return [...new Set([...UNITS_ALL(),...Object.keys(k.asg),...kpPeople().map(c=>c.unit).filter(Boolean)])]}
function uScore(u){const k=kpCfg(),d=[...new Set((k.asg[u]||[]).concat(temTeams(u).flatMap(t=>P.filter(p=>teamsOf(p).includes(t)).map(p=>p.n))))].map(n=>P.find(p=>p.n===n)).filter(Boolean),pm=d.filter(isPMO),cm=d.filter(isCMO),cs=kpPeople().filter(c=>c.unit===u&&(typeof kpOn==='function'?kpOn:()=>true)(c)),c={pmo:cs.filter(x=>(x.peran||[]).includes('pmo')),cmo:cs.filter(x=>(x.peran||[]).includes('cmo')),pb:cs.filter(x=>(x.peran||[]).includes('probis'))},miss=[];if(!pm.length)miss.push('PMO Kemenkeu');if(!cm.length)miss.push('CMO Kemenkeu');if(!c.pmo.length)miss.push('PMO Unit');if(!c.cmo.length)miss.push('CMO Unit');if(!c.pb.length)miss.push('Pemilik Probis');return {pm,cm,c,miss,sc:5-miss.length}}
const ringC=sc=>sc===5?'var(--t-o)':sc>=3?'#D99A00':'var(--t-c)',ring=sc=>'<span class="t-ring" style="background:conic-gradient('+ringC(sc)+' '+(sc*72)+'deg,#E9EDF4 0)" title="Kelengkapan '+sc+' dari 5"><span style="color:var(--t-navy)">'+sc+'/5</span></span>';
const fmtHp=h=>{const raw=String(h||'').trim();let d=raw.replace(/[^\d*]/g,'');if(!d||/\*/.test(d))return raw;if(d.startsWith('62'))d='0'+d.slice(2);else if(d.startsWith('8'))d='0'+d;return d.length>=9?[d.slice(0,4),d.slice(4,8),d.slice(8)].filter(Boolean).join('-'):raw};
const KLB={pmo:'PMO',cmo:'CMO',probis:'Pemilik Proses Bisnis'};
const kKeys=c=>['pmo','cmo','probis'].filter(k=>(c.peran||[]).includes(k));
const kCol=c=>{const k=kKeys(c);return k.includes('pmo')&&k.includes('cmo')?'#7B4FC9':k.includes('pmo')?'#2F6FCE':k.includes('cmo')?'#5B4BC4':k.includes('probis')?'#17785A':'#7E889B'};
const kLbl=c=>{const l=kKeys(c).map(k=>KLB[k]);return l.length<=1?(l[0]||'Kontak'):l.slice(0,-1).join(', ')+' & '+l[l.length-1]};
const kSort=L=>L.slice().sort((a,b)=>{const r=c=>{const k=kKeys(c);return k.includes('pmo')?0:k.includes('cmo')?1:2};return r(a)-r(b)||String(a.nama).localeCompare(String(b.nama))});
