 const vt='<div class="t-seg" style="padding:2px"><button type="button" data-tuv="prof" class="'+(view==='prof'?'t-on':'')+'">'+ic('idc','s')+'Profil kontak</button><button type="button" data-tuv="ring" class="'+(view==='ring'?'t-on':'')+'">'+ic('layout','s')+'Kelengkapan</button></div>';
