 if((el=g('[data-tcud]'))){const v=+el.dataset.tcud,rt=realT();ST.cuD=v===0?'':addD(ST.cuD||rt,v);if(ST.cuD===rt)ST.cuD='';const d=ST.cuD||rt;ST.calY=+d.slice(0,4);ST.calM=+d.slice(5,7)-1;ST.calSel=d;rr();return}
