async function impRead(kind,files,prog){const out=[];
 if(kind==='json'){for(const f of files){const j=JSON.parse(await f.text());const arr=Array.isArray(j)?j:Array.isArray(j.data)?j.data:Array.isArray(j.resources)?j.resources:Array.isArray(j.pegawai)?j.pegawai:[];
   if(!arr.length)throw new Error('File JSON tidak berisi daftar pegawai.');arr.forEach(r=>out.push(Array.isArray(r.jabatan)||r.nip18?mapSK(r):r.emailKemenkeu!==undefined||r.penugasan!==undefined?Object.assign(mapRow(r),{_dcm:r}):mapRow(r)))}}
 else if(kind==='xlsx'){for(const f of files){if(typeof XLSX==='undefined')throw new Error('Pustaka Excel belum termuat. Periksa koneksi lalu muat ulang halaman.');const wb=XLSX.read(await f.arrayBuffer(),{type:'array',raw:/\.csv$/i.test(f.name)});const ws=wb.Sheets[wb.SheetNames[0]];XLSX.utils.sheet_to_json(ws,{defval:'',raw:false}).forEach(r=>out.push(mapRow(r)))}}
 else{let i=0;for(const f of files){i++;if(!/^image\//.test(f.type))continue;prog('Membaca gambar '+i+' dari '+files.length+'…');const img=await kqLoadImage(await kqDataUrl(f));kqProgress=m=>{if(m&&m.status==='recognizing text')prog('Gambar '+i+'/'+files.length+': membaca teks '+Math.round((m.progress||0)*100)+'%')};
   let r;try{r=kqParseProfile(await kqRunOcr(img))}finally{kqProgress=null}let foto='';try{foto=kqCropAvatar(img,r)||''}catch(e){}
   out.push({n:r.nama||'',nip:r.nip||'',jab:r.jabatan||'',org:r.unitKerja||'',pang:r.pangkat||'',emailK:/@kemenkeu\.go\.id$/i.test(r.email||'')?r.email:'',hp:/\*/.test(r.hp||'')?'':(r.hp||''),foto,str:strSlot(r.jabatan,r.unitKerja),_ocr:f.name})}}
 return out.filter(o=>o.n)}
